import React, { type PropsWithChildren } from 'react';

import { XYChartDataContext } from '../context/XYChartData.context.js';
import { getMinMax } from '../functions/get-min-max.js';
import type { XYChartData, XYChartVariants } from '../types/xy-chart.js';

interface XYChartChartDataProviderProps {
  seriesVariantsProps: XYChartVariants[];
  data: XYChartData[];
}

export const XYChartChartDataProvider = ({
  seriesVariantsProps,
  data,
  children,
}: PropsWithChildren<XYChartChartDataProviderProps>) => {
  const { minMaxY, minMaxValue } = getMinMax(seriesVariantsProps, data);
  return (
    <XYChartDataContext.Provider
      value={{
        minMaxY,
        minMaxValue,
        seriesVariantsProps,
        data,
      }}
    >
      {children}
    </XYChartDataContext.Provider>
  );
};

XYChartChartDataProvider['displayName'] = 'XYChartChartDataProvider';
